use std::collections::HashMap;
use tokio::process::Child;
use uuid::Uuid;

pub struct ProcessManager {
    processes: HashMap<Uuid, u32>,
}

impl ProcessManager {
    pub fn new() -> Self {
        Self {
            processes: HashMap::new(),
        }
    }

    pub fn register_process(&mut self, id: Uuid, pid: u32) {
        self.processes.insert(id, pid);
    }

    pub fn unregister_process(&mut self, id: Uuid) {
        self.processes.remove(&id);
    }

    pub fn kill_process(&mut self, id: Uuid) {
        if let Some(pid) = self.processes.remove(&id) {
            unsafe {
                libc::kill(pid as i32, libc::SIGTERM);
            }
        }
    }

    pub fn kill_all(&mut self) {
        for (_, pid) in self.processes.drain() {
            unsafe {
                libc::kill(pid as i32, libc::SIGTERM);
            }
        }
    }
}

impl Default for ProcessManager {
    fn default() -> Self {
        Self::new()
    }
}
