    pub project_id: Uuid,
    pub workflow_id: Uuid,
    pub command: String,
}

pub async fn start_run(
    State(state): State<AppState>,
    Path(run_id): Path<Uuid>,
    Json(req): Json<StartRunRequest>,
) -> StatusCode {
    let workspace_dir = format!("{}/{}", state.config.workspace_dir, req.project_id);

    tokio::fs::create_dir_all(&workspace_dir).await.ok();

    sqlx::query("UPDATE runs SET status = 'running' WHERE id = $1")
        .bind(run_id)
        .execute(&state.db)
        .await
        .ok();

    let db = state.db.clone();
    let command = req.command.clone();

    tokio::spawn(async move {
        let result = Command::new("sh")
            .arg("-c")
            .arg(&command)
            .current_dir(&workspace_dir)
            .output()
            .await;

        let (status, exit_code) = match result {
            Ok(output) => {
                if output.status.success() {
                    ("success", output.status.code())
                } else {
                    ("failed", output.status.code())
                }
            }
            Err(_) => ("failed", Some(-1)),
        };

        sqlx::query("UPDATE runs SET status = $1, exit_code = $2, finished_at = NOW() WHERE id = $3")
            .bind(status)
            .bind(exit_code)
            .bind(run_id)
            .execute(&db)
            .await
            .ok();
    });

    StatusCode::ACCEPTED
}

pub async fn stop_run(
    State(state): State<AppState>,
    Path(run_id): Path<Uuid>,
) -> StatusCode {
    let mut manager = PROCESS_MANAGER.write().await;
    manager.kill_process(run_id);

    sqlx::query("UPDATE runs SET status = 'cancelled', finished_at = NOW() WHERE id = $1")
        .bind(run_id)
        .execute(&state.db)
        .await
        .ok();

    StatusCode::NO_CONTENT
}

pub async fn get_logs(
    State(state): State<AppState>,
    Path(run_id): Path<Uuid>,
) -> Json<serde_json::Value> {
    let run = sqlx::query_as::<_, (Option<String>,)>(
        "SELECT logs_url FROM runs WHERE id = $1"
    )
    .bind(run_id)
    .fetch_optional(&state.db)
    .await
    .ok()
    .flatten();

    Json(serde_json::json!({
        "run_id": run_id,
        "logs": run.and_then(|r| r.0).unwrap_or_default()
    }))
}

#[derive(serde::Deserialize)]
pub struct RebuildRequest {
    pub nix_config: String,
}

pub async fn rebuild_environment(
    State(state): State<AppState>,
    Path(project_id): Path<Uuid>,
    Json(req): Json<RebuildRequest>,
) -> StatusCode {
    let workspace_dir = format!("{}/{}", state.config.workspace_dir, project_id);
    tokio::fs::create_dir_all(&workspace_dir).await.ok();

    let flake_path = format!("{}/flake.nix", workspace_dir);
    tokio::fs::write(&flake_path, &req.nix_config).await.ok();

    let result = Command::new("nix")
        .args(["flake", "check", "."])
        .current_dir(&workspace_dir)
        .output()
        .await;

    match result {
        Ok(output) if output.status.success() => {
            let _ = Command::new("nix")
                .args(["develop", ".", "--command", "true"])
                .current_dir(&workspace_dir)
                .output()
                .await;
            StatusCode::OK
        }
        _ => StatusCode::BAD_REQUEST,
    }
}

pub async fn terminal_ws(
    ws: WebSocketUpgrade,
    Path(project_id): Path<Uuid>,
    State(state): State<AppState>,
) -> Response {
    ws.on_upgrade(move |socket| handle_terminal(socket, project_id, state))
}

async fn handle_terminal(socket: WebSocket, project_id: Uuid, state: AppState) {
    let (mut sender, mut receiver) = socket.split();

    let workspace_dir = format!("{}/{}", state.config.workspace_dir, project_id);
    tokio::fs::create_dir_all(&workspace_dir).await.ok();

    let mut child = match Command::new("sh")
        .current_dir(&workspace_dir)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
    {
        Ok(child) => child,
        Err(_) => return,
    };

    let mut stdin = child.stdin.take().unwrap();
    let stdout = child.stdout.take().unwrap();
    let stderr = child.stderr.take().unwrap();

    let mut stdout_reader = BufReader::new(stdout).lines();
    let mut stderr_reader = BufReader::new(stderr).lines();

    let sender_clone = Arc::new(tokio::sync::Mutex::new(sender));
    let sender_for_stdout = sender_clone.clone();
    let sender_for_stderr = sender_clone.clone();

    let stdout_task = tokio::spawn(async move {
        while let Ok(Some(line)) = stdout_reader.next_line().await {
            let msg = serde_json::json!({"type": "stdout", "data": line});
            let mut sender = sender_for_stdout.lock().await;
            if sender.send(Message::Text(msg.to_string())).await.is_err() {
                break;
            }
        }
    });

    let stderr_task = tokio::spawn(async move {
        while let Ok(Some(line)) = stderr_reader.next_line().await {
            let msg = serde_json::json!({"type": "stderr", "data": line});
            let mut sender = sender_for_stderr.lock().await;
            if sender.send(Message::Text(msg.to_string())).await.is_err() {
                break;
            }
        }
    });

    let stdin_task = tokio::spawn(async move {
        while let Some(Ok(msg)) = receiver.next().await {
            if let Message::Text(text) = msg {
                if let Ok(input) = serde_json::from_str::<serde_json::Value>(&text) {
                    if let Some(data) = input["data"].as_str() {
                        if stdin.write_all(data.as_bytes()).await.is_err() {
                            break;
                        }
                        if stdin.write_all(b"\n").await.is_err() {
                            break;
                        }
                        stdin.flush().await.ok();
                    }
                }
            } else if let Message::Close(_) = msg {
                break;
            }
        }
    });

    tokio::select! {
        _ = stdout_task => {},
        _ = stderr_task => {},
        _ = stdin_task => {},
    }

    child.kill().await.ok();
}

pub async fn lsp_proxy(
    ws: WebSocketUpgrade,
    Path(project_id): Path<Uuid>,
    State(state): State<AppState>,
) -> Response {
    ws.on_upgrade(move |socket| handle_lsp(socket, project_id, state))
}

async fn handle_lsp(socket: WebSocket, project_id: Uuid, state: AppState) {
    let (mut sender, mut receiver) = socket.split();

    let workspace_dir = format!("{}/{}", state.config.workspace_dir, project_id);

    let mut child = match Command::new("typescript-language-server")
        .args(["--stdio"])
        .current_dir(&workspace_dir)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
    {
        Ok(child) => child,
        Err(_) => return,
    };

    let mut stdin = child.stdin.take().unwrap();
    let stdout = child.stdout.take().unwrap();

    let mut stdout_reader = BufReader::new(stdout);

    let sender_arc = Arc::new(tokio::sync::Mutex::new(sender));
    let sender_for_read = sender_arc.clone();

    let read_task = tokio::spawn(async move {
        let mut buffer = String::new();
        loop {
            buffer.clear();
            match stdout_reader.read_line(&mut buffer).await {
                Ok(0) => break,
                Ok(_) => {
                    let mut sender = sender_for_read.lock().await;
                    if sender.send(Message::Text(buffer.clone())).await.is_err() {
                        break;
                    }
                }
                Err(_) => break,
            }
        }
    });

    let write_task = tokio::spawn(async move {
        while let Some(Ok(msg)) = receiver.next().await {
            if let Message::Text(text) = msg {
                let content_length = text.len();
                let header = format!("Content-Length: {}\r\n\r\n", content_length);
                if stdin.write_all(header.as_bytes()).await.is_err() {
                    break;
                }
                if stdin.write_all(text.as_bytes()).await.is_err() {
                    break;
                }
                stdin.flush().await.ok();
            } else if let Message::Close(_) = msg {
                break;
            }
        }
    });

    tokio::select! {
        _ = read_task => {},
        _ = write_task => {},
    }

    child.kill().await.ok();
}

#[derive(serde::Deserialize)]
pub struct BuildDeploymentRequest {
    pub project_id: Uuid,
    pub environment: String,
}

pub async fn build_deployment(
    State(state): State<AppState>,
    Path(deployment_id): Path<Uuid>,
    Json(req): Json<BuildDeploymentRequest>,
) -> StatusCode {
    let db = state.db.clone();
    let workspace_dir = format!("{}/{}", state.config.workspace_dir, req.project_id);

    tokio::spawn(async move {
        sqlx::query("UPDATE deployments SET status = 'building' WHERE id = $1")
            .bind(deployment_id)
            .execute(&db)
            .await
            .ok();

        let dockerfile = r#"FROM nixos/nix:latest
WORKDIR /app
COPY . .
RUN nix-build
CMD ["./result/bin/app"]
"#;

        tokio::fs::write(format!("{}/Dockerfile", workspace_dir), dockerfile).await.ok();

        let image_tag = format!("clouddev/project-{}:{}", req.project_id, deployment_id);

        let build_result = Command::new("docker")
            .args(["build", "-t", &image_tag, "."])
            .current_dir(&workspace_dir)
            .output()
            .await;

        match build_result {
            Ok(output) if output.status.success() => {
                sqlx::query("UPDATE deployments SET status = 'deploying', image_url = $1 WHERE id = $2")
                    .bind(&image_tag)
                    .bind(deployment_id)
                    .execute(&db)
                    .await
                    .ok();

                let public_url = format!("", deployment_id);

                sqlx::query("UPDATE deployments SET status = 'active', public_url = $1, deployed_at = NOW() WHERE id = $2")
                    .bind(&public_url)
                    .bind(deployment_id)
                    .execute(&db)
                    .await
                    .ok();
            }
            _ => {
                sqlx::query("UPDATE deployments SET status = 'failed' WHERE id = $1")
                    .bind(deployment_id)
                    .execute(&db)
                    .await
                    .ok();
            }
        }
    });

    StatusCode::ACCEPTED
}
