use anyhow::Result;
use std::path::Path;
use tokio::process::Command;

pub struct SandboxConfig {
    pub memory_limit_mb: u64,
    pub cpu_limit_percent: u32,
    pub network_enabled: bool,
    pub read_only_paths: Vec<String>,
    pub read_write_paths: Vec<String>,
}

impl Default for SandboxConfig {
    fn default() -> Self {
        Self {
            memory_limit_mb: 512,
            cpu_limit_percent: 50,
            network_enabled: true,
            read_only_paths: vec!["/nix/store".to_string()],
            read_write_paths: vec![],
        }
    }
}

pub async fn run_in_sandbox(
    command: &str,
    working_dir: &Path,
    config: &SandboxConfig,
) -> Result<std::process::Output> {
    let mut args = vec![
        "--unshare-all".to_string(),
        "--share-net".to_string(),
        "--die-with-parent".to_string(),
        "--chdir".to_string(),
        working_dir.to_string_lossy().to_string(),
    ];

    for path in &config.read_only_paths {
        args.push("--ro-bind".to_string());
        args.push(path.clone());
        args.push(path.clone());
    }

    for path in &config.read_write_paths {
        args.push("--bind".to_string());
        args.push(path.clone());
        args.push(path.clone());
    }

    args.push("--bind".to_string());
    args.push(working_dir.to_string_lossy().to_string());
    args.push(working_dir.to_string_lossy().to_string());

    args.push("sh".to_string());
    args.push("-c".to_string());
    args.push(command.to_string());

    let output = Command::new("bwrap")
        .args(&args)
        .output()
        .await?;

    Ok(output)
}

pub async fn run_with_cgroups(
    command: &str,
    working_dir: &Path,
    config: &SandboxConfig,
) -> Result<std::process::Output> {
    let cgroup_args = format!(
        "systemd-run --scope --user -p MemoryMax={}M -p CPUQuota={}% --",
        config.memory_limit_mb,
        config.cpu_limit_percent
    );

    let full_command = format!("{} sh -c '{}'", cgroup_args, command);

    let output = Command::new("sh")
        .arg("-c")
        .arg(&full_command)
        .current_dir(working_dir)
        .output()
        .await?;

    Ok(output)
}
